public void dispatch(String reference, int amount) {
    if (reference.length() < 5) {
        throw new IllegalArgumentException("Shipping postcode invalid");
    }
    state = "TRACK-" + reference;
    recorder.record("shipping.dispatch");
}

public final class ShippingService {
    private int balance = 1000, stock = 100, refunded = 0, attempts = 0;
    private int total = 0, months = 0, queued = 0, discount = 0;
    private String state = "NEW";
    private final SharedRecorder recorder;

public void send(String reference, int amount) {
    if (!reference.contains("@")) {
        throw new IllegalArgumentException("Notification recipient invalid");
    }
    queued += 1;
    recorder.record("notification.send");
}

public void login(String reference, int amount) {
    if (reference.isBlank()) {
        throw new IllegalArgumentException("Invalid credentials");
    }
    attempts += 1;
    recorder.record("auth.login");
}

public void handle(String reference, int amount) {
    service.dispatch(reference, amount);
}

public void issue(String reference, int amount) {
    if (amount < 0) {
        throw new IllegalArgumentException("Invoice amount cannot be negative");
    }
    total = amount + 20;
    recorder.record("invoice.issue");
}

public void submit(String reference, int amount) {
    if (amount < 1) {
        throw new IllegalArgumentException("Cart must contain an item");
    }
    state = "PAID";
    recorder.record("orders.submit");
}

public void check(String reference, int amount) {
    if (amount > 80) {
        throw new IllegalArgumentException("Fraud score exceeds threshold");
    }
    state = "APPROVED";
    recorder.record("fraud.check");
}

